window.BANK_PARTS=window.BANK_PARTS||{};
window.BANK_PARTS["interview_technical"]={"name":"Technical interview","ata":"INT","featured":true,"questions":[
{"q":"¿Qué diferencia esencial existe entre un METAR y un TAF?","options":["El METAR informa condiciones observadas; el TAF pronostica condiciones futuras del aeródromo","El METAR pronostica condiciones futuras del aeródromo; el TAF informa únicamente lo observado en tiempo real","Ambos informan condiciones observadas, pero el METAR corresponde a rutas y el TAF a aeródromos específicos","El METAR y el TAF son el mismo reporte; solo cambia el nombre según el país que lo emite"],"correct":0,"expl":"METAR describe condiciones meteorológicas observadas en un aeródromo; TAF es un pronóstico para un período determinado.","cite":"Origen: Resumen preguntas LATAM, preguntas 1–2. Revisión: terminología meteorológica operacional estándar.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame la diferencia operacional entre un METAR y un TAF."},
{"q":"¿Qué caracteriza a un SPECI/ESPECI?","options":["Es un reporte especial emitido cuando ocurren cambios meteorológicos significativos que justifican informar antes del siguiente reporte rutinario","Es un reporte rutinario adicional emitido cada 15 minutos, independientemente de si existen cambios meteorológicos relevantes para ese aeródromo en particular","Es una ampliación del TAF que agrega pronósticos de turbulencia y engelamiento previstos para las próximas horas de validez del pronóstico","Es la denominación que recibe el METAR cuando se transmite fuera del horario habitual de la torre de control local del aeródromo"],"correct":0,"expl":"Un SPECI/ESPECI es una observación meteorológica especial; se emite cuando cambios significativos requieren informar sin esperar al METAR rutinario.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen preguntas LATAM. Revisión: definición operacional estándar.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es un SPECI o ESPECI y cuándo esperas verlo?"},
{"q":"¿Qué es un PIREP?","options":["Un reporte de condiciones meteorológicas encontradas en vuelo realizado por un piloto","Un reporte de condiciones meteorológicas pronosticadas para las próximas 24 horas, emitido por el servicio meteorológico","Un aviso emitido por ATC cuando detecta turbulencia en el radar de ruta","Un registro obligatorio que el piloto entrega a la torre antes de cada despegue"],"correct":0,"expl":"El PIREP comunica condiciones realmente encontradas en vuelo y puede aportar información relevante para otras tripulaciones y servicios meteorológicos.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen preguntas LATAM, PIREP.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es un PIREP y por qué puede ser importante para otro piloto?"},
{"q":"¿Qué indica CAVOK cuando se utiliza en un reporte meteorológico?","options":["Que se cumplen simultáneamente criterios establecidos de buena visibilidad, ausencia de tiempo significativo y nubosidad relevante bajo los límites aplicables","Que la visibilidad es exactamente 10 km en todas direcciones y no existe ningún tipo de nube significativa en el cielo visible en ese momento","Que las condiciones meteorológicas permiten operar únicamente bajo reglas de vuelo visual, sin ninguna excepción posible durante todo ese período de validez","Que el viento de superficie es inferior a 10 kt y la temperatura supera al punto de rocío en al menos 5 grados centígrados en el aeródromo"],"correct":0,"expl":"CAVOK resume un conjunto de condiciones de visibilidad, nubosidad y tiempo significativo; no significa simplemente “cielo despejado”.","cite":"Origen: Resumen preguntas LATAM, CAVOK. Respuesta depurada para evitar una definición demasiado absoluta.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué te está diciendo realmente CAVOK?"},
{"q":"¿Qué describe mejor un microburst?","options":["Una intensa corriente descendente localizada que al alcanzar la superficie se expande horizontalmente y puede producir fuerte windshear","Una corriente ascendente localizada que se forma bajo el yunque de un cumulonimbus ya en fase madura de desarrollo convectivo","Un fenómeno de turbulencia en aire claro que ocurre exclusivamente a gran altitud, muy lejos de cualquier nube o actividad convectiva cercana","Una racha de viento horizontal sostenida asociada exclusivamente al paso de un frente frío débil y poco activo en la zona"],"correct":0,"expl":"Un microburst combina una fuerte corriente descendente y divergencia cerca del suelo, por lo que puede provocar cambios muy rápidos de viento y performance.","cite":"Origen: PREGUNTAS TÉCNICAS / PREGUNTAS LATAM / Resumen LATAM, microburst.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Define microburst y explícame por qué es especialmente peligroso cerca del suelo."},
{"q":"¿Cuál es la característica esencial del windshear?","options":["Un cambio significativo de velocidad y/o dirección del viento en una distancia relativamente corta","Una disminución gradual y constante de la velocidad del viento a medida que aumenta la altitud","Un fenómeno que solo se produce dentro de nubes de tormenta y nunca ocurre en aire despejado o claro","Una diferencia de temperatura entre dos masas de aire que provoca turbulencia mecánica en la zona"],"correct":0,"expl":"El windshear es un gradiente de viento; operacionalmente importa porque modifica rápidamente la componente de viento y la energía de la aeronave.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, windshear.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es windshear y qué le hace a la energía del avión?"},
{"q":"¿Qué es virga?","options":["Precipitación que cae desde una nube pero se evapora o sublima antes de alcanzar el suelo","Precipitación helada que se acumula formando hielo transparente sobre las superficies del avión","Una franja de nubes bajas que se forma por enfriamiento nocturno del terreno","Un tipo de granizo que se derrite completamente antes de tocar la punta del ala"],"correct":0,"expl":"La virga es precipitación que no llega al suelo. Su evaporación puede favorecer enfriamiento y corrientes descendentes, por lo que puede asociarse a windshear/microburst.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, virga.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es virga y qué riesgo operacional puede acompañarla?"},
{"q":"¿Qué fase de una tormenta presenta simultáneamente corrientes ascendentes y descendentes?","options":["La fase madura","La fase de desarrollo inicial","La fase de disipación","La fase posterior al colapso"],"correct":0,"expl":"La fase madura es la de mayor actividad: coexisten updrafts y downdrafts, normalmente junto con precipitación y los peligros más severos.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, formación de tormentas.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Cuáles son las etapas de una tormenta y cuál suele ser la más peligrosa?"},
{"q":"¿Qué condición meteorológica se asocia típicamente a un frente frío activo?","options":["Ascenso rápido del aire cálido, nubosidad de desarrollo vertical, chubascos y posible actividad convectiva","Descenso lento del aire frío, cielos despejados y ausencia total de precipitación en toda la zona frontal cercana","Nubosidad estratiforme extensa con lluvia ligera y continua, sin cambios bruscos de viento en superficie","Elevación gradual de ambas masas de aire con neblina persistente y visibilidad reducida en la zona"],"correct":0,"expl":"El aire frío más denso fuerza el ascenso del aire cálido; cuando existe suficiente humedad e inestabilidad puede producir desarrollo vertical, precipitación intensa y tormentas.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, frente frío.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué tiempo esperas alrededor de un frente frío activo?"},
{"q":"¿Qué describe un frente ocluido?","options":["La situación en que un frente frío alcanza a un frente cálido y eleva el aire cálido desde la superficie","La situación en que un frente cálido alcanza a un frente frío y ambos se disipan por completo sin nubosidad","El límite estacionario entre dos masas de aire de igual temperatura y humedad que no se desplaza en varios días","Una zona de baja presión que se forma exclusivamente sobre superficies oceánicas cálidas en verano"],"correct":0,"expl":"Una oclusión se desarrolla cuando el frente frío alcanza al cálido, modificando la estructura frontal y elevando el aire cálido.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, frente ocluido.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Cómo se forma un frente ocluido?"},
{"q":"¿Qué nube representa normalmente el mayor riesgo convectivo para una aeronave?","options":["Cumulonimbus","Cirrus","Stratus","Altostratus"],"correct":0,"expl":"El cumulonimbus puede concentrar turbulencia severa, windshear, granizo, hielo, rayos y fuertes corrientes verticales.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, nubes a evitar.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué peligros te hacen evitar un cumulonimbus?"},
{"q":"¿Por qué una nube lenticular merece atención operacional?","options":["Porque puede indicar ondas de montaña y fuertes movimientos verticales/turbulencia en su entorno","Porque garantiza cielo despejado y ausencia total de turbulencia en toda la ruta de vuelo prevista","Porque indica formación inminente de un cumulonimbus en las próximas horas sobre la zona","Porque señala presencia de hielo en la capa límite cercana a la superficie del terreno"],"correct":0,"expl":"Las lenticulares se forman frecuentemente en ondas orográficas y pueden ser una señal visual de flujo fuerte y turbulencia asociada a montaña.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, nube lenticular.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Ves una nube lenticular cerca de una cordillera. ¿Qué te sugiere sobre el flujo de aire?"},
{"q":"¿Qué representa una línea isobárica en una carta meteorológica?","options":["Une puntos de igual presión atmosférica","Une puntos de igual temperatura del aire","Une puntos de igual velocidad de viento","Une puntos de igual altura de terreno"],"correct":0,"expl":"Las isobaras conectan puntos con igual presión; su espaciamiento ayuda a interpretar el gradiente de presión.","cite":"Origen: PREGUNTAS LATAM 2022, línea isobárica.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es una isobara y qué te sugiere un fuerte gradiente de presión?"},
{"q":"¿Qué representa una línea isogónica?","options":["Une puntos de igual variación o declinación magnética","Une puntos de igual inclinación magnética vertical","Une puntos de igual intensidad del campo magnético","Une puntos de igual rumbo verdadero respecto al norte"],"correct":0,"expl":"Las líneas isogónicas unen lugares con la misma variación magnética y sirven para relacionar referencias verdaderas y magnéticas.","cite":"Origen: PREGUNTAS LATAM 2022, línea isogónica.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Meteorology","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es una línea isogónica?"},
{"q":"¿Qué representa TORA?","options":["La longitud de pista declarada disponible y adecuada para la carrera de despegue","La longitud de pista declarada disponible y adecuada para la carrera de aterrizaje","La distancia total disponible para acelerar, detenerse y despejar la pista con margen","La distancia mínima exigida entre el umbral y el punto de rotación calculado"],"correct":0,"expl":"TORA es la Take-Off Run Available: longitud declarada disponible para la carrera de despegue.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM. Revisión: ICAO declared distances.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Define TORA."},
{"q":"¿Cómo se relaciona TODA con TORA?","options":["TODA es TORA más la clearway disponible, cuando existe","TODA es TORA menos la clearway no utilizable para ese despegue","TODA es TORA multiplicada por un factor de seguridad fijo del 1.15","TODA es independiente de TORA y se calcula solo con el peso de despegue"],"correct":0,"expl":"TODA incorpora la TORA y la clearway declarada utilizable para la trayectoria inicial de despegue.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM. Revisión: ICAO declared distances.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Define TODA y su relación con TORA."},
{"q":"¿Cómo se relaciona ASDA con TORA?","options":["ASDA es TORA más la stopway disponible, cuando existe","ASDA es TORA menos la porción de pista contaminada, cuando existe","ASDA es TORA dividida por el coeficiente de fricción de la pista","ASDA es independiente de TORA y depende solo de VREF"],"correct":0,"expl":"ASDA es la Accelerate-Stop Distance Available y puede incluir la stopway declarada.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM. Revisión: ICAO declared distances.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Define ASDA."},
{"q":"¿Qué representa LDA?","options":["La longitud de pista declarada disponible y adecuada para la carrera de aterrizaje","La longitud de pista declarada disponible y adecuada para la carrera de despegue","La distancia entre el umbral desplazado y el punto de toma de contacto de la pista","La distancia adicional que se suma automáticamente en pista mojada según el cálculo"],"correct":0,"expl":"LDA es la Landing Distance Available: longitud declarada disponible y adecuada para la carrera de aterrizaje.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM. Revisión: ICAO declared distances.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Define LDA."},
{"q":"¿Qué expresa el concepto de balanced field en términos de performance de despegue?","options":["Una condición en la que la distancia requerida para continuar el despegue y la requerida para rechazarlo quedan equilibradas bajo las hipótesis aplicables","Una condición en la que la pista tiene exactamente la misma pendiente longitudinal medida en ambos sentidos de despegue disponibles en ese aeródromo específico","Una condición en la que el peso de despegue coincide exactamente con el peso máximo certificado de aterrizaje de esa aeronave en particular","Una condición en la que V1 y V2 se calculan siempre como el mismo valor numérico exacto por margen de seguridad aplicado"],"correct":0,"expl":"El concepto de balanced field relaciona las soluciones accelerate-go y accelerate-stop; no debe confundirse simplemente con que las distancias declaradas del aeropuerto sean iguales.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM. Respuesta corregida para evitar la simplificación ASDA = TODA.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué significa realmente balanced field?"},
{"q":"¿Cuál es la relación correcta entre IAS, CAS, TAS y GS?","options":["IAS es la lectura indicada; CAS corrige errores de instrumento/posición; TAS representa la velocidad respecto de la masa de aire; GS es la velocidad respecto del suelo","IAS es la velocidad respecto del suelo; CAS es la corrección por temperatura exterior; TAS es la lectura directa sin corregir; GS depende únicamente del viento de cola en ese tramo","IAS y CAS son idénticas en todo el envelope de vuelo; TAS se calcula sumando directamente el viento de cola a la IAS indicada en cada momento","CAS es la velocidad respecto de la masa de aire; TAS es la lectura indicada sin ninguna corrección; GS es la componente vertical del viento en ruta"],"correct":0,"expl":"Las cuatro velocidades describen referencias diferentes. La GS incorpora el efecto del viento sobre el movimiento respecto del terreno.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, IAS-CAS-TAS-GS.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame IAS, CAS, TAS y GS sin limitarte a recitar las siglas."},
{"q":"¿Qué representa L/D max?","options":["La condición de máxima relación sustentación/resistencia y, por tanto, máxima eficiencia aerodinámica","La condición de máximo coeficiente de sustentación, independientemente de la resistencia generada","La velocidad a la que el motor entrega su máxima potencia disponible en cualquier altitud de vuelo en crucero","La condición de mínima resistencia parásita, sin considerar en ningún caso la resistencia inducida"],"correct":0,"expl":"L/D max identifica el punto de mayor eficiencia aerodinámica; en planeo se relaciona con el mejor ángulo/distancia en aire calmo para una configuración determinada.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, L/D max. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es L/D max y por qué importa?"},
{"q":"¿Cómo varían, en términos generales, la resistencia inducida y la resistencia parásita con la velocidad?","options":["La inducida predomina a baja velocidad y disminuye al aumentar velocidad; la parásita aumenta con la velocidad","La parásita predomina a baja velocidad y disminuye al aumentar velocidad; la inducida aumenta con la velocidad","Ambas aumentan de forma idéntica y proporcional a medida que se incrementa la velocidad","La inducida depende solo de la densidad del aire y no varía con la velocidad ni la sustentación"],"correct":0,"expl":"La resistencia inducida está asociada a la producción de sustentación y domina a velocidades bajas; la parásita crece con la velocidad. Su suma genera la curva de drag total.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, drag inducido/parásito.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Cómo cambia el drag inducido y el drag parásito cuando aceleras?"},
{"q":"¿Para qué se utilizan los vortex generators?","options":["Para energizar la capa límite y retrasar la separación del flujo en zonas donde interesa mantenerlo adherido","Para reducir la velocidad del flujo de aire local y forzar deliberadamente una separación temprana en el borde de salida","Para generar sustentación adicional de forma directa, cumpliendo una función equivalente a la de un flap suplementario","Para disipar la electricidad estática acumulada en el fuselaje durante el vuelo en atmósfera muy seca"],"correct":0,"expl":"Los vortex generators mezclan aire de mayor energía con la capa límite y ayudan a mantener el flujo adherido.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, vortex generators.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué hace un vortex generator aerodinámicamente?"},
{"q":"¿Cuál es el propósito aerodinámico común de winglets y sharklets?","options":["Reducir las pérdidas asociadas a los vórtices de punta y mejorar la eficiencia aerodinámica","Aumentar deliberadamente la resistencia inducida para mejorar la estabilidad direccional en crucero","Servir como superficie de control adicional para el guiñado en caso de falla del timón","Incrementar el área alar total para reducir la velocidad de pérdida en aterrizaje"],"correct":0,"expl":"Ambos son dispositivos de punta alar destinados a mejorar eficiencia reduciendo las pérdidas asociadas al flujo tridimensional y vórtices de punta.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, winglet y sharklet. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué problema aerodinámico intentan reducir un winglet o un sharklet?"},
{"q":"¿Qué es el ángulo de ataque?","options":["El ángulo entre la cuerda aerodinámica del perfil y el viento relativo","El ángulo entre la cuerda aerodinámica del perfil y el horizonte verdadero","El ángulo entre el eje longitudinal del fuselaje y la trayectoria de vuelo","El ángulo entre la superficie alar y la línea de crucero seleccionada en el FMS"],"correct":0,"expl":"El ángulo de ataque se define respecto del viento relativo, no respecto del horizonte.","cite":"Origen: Material de entrevista LATAM, perfil alar/cuerda y stall. Revisión conceptual de aerodinámica.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Define ángulo de ataque."},
{"q":"¿Cuál es la causa aerodinámica fundamental de un stall?","options":["Exceder el ángulo de ataque crítico","Descender por debajo de una velocidad mínima fija","Reducir la potencia del motor por debajo de idle","Superar el peso máximo estructural certificado"],"correct":0,"expl":"Un stall ocurre cuando el ala supera su ángulo de ataque crítico. La velocidad a la que ocurre depende de carga, configuración y otras condiciones.","cite":"Origen: Resumen preguntas LATAM, stall. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué causa realmente un stall?"},
{"q":"¿Qué efecto tiene desplazar el centro de gravedad hacia delante, en términos generales?","options":["Aumenta la estabilidad longitudinal pero suele exigir mayor fuerza de cola y puede penalizar performance","Reduce la estabilidad longitudinal pero disminuye la fuerza de cola necesaria y mejora la performance","No modifica en absoluto la estabilidad longitudinal, solo desplaza el punto de aplicación del peso vacío","Elimina completamente la necesidad de ajustar el estabilizador horizontal antes de cada despegue programado"],"correct":0,"expl":"Un CG más adelantado aumenta el brazo estabilizador requerido y normalmente mejora la estabilidad, a costa de mayores fuerzas/trim y posibles penalizaciones de performance.","cite":"Origen: Resumen preguntas LATAM, CG. Revisión conceptual de weight & balance.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué cambia cuando el CG se mueve hacia delante?"},
{"q":"¿Qué es el Mach crítico?","options":["El Mach de vuelo más bajo al que aparece flujo local sónico en algún punto de la aeronave","El Mach máximo al que puede volar la aeronave sin exceder ninguna limitación estructural","El Mach exacto al que toda la superficie del avión alcanza velocidad supersónica simultáneamente","El Mach mínimo requerido para mantener control efectivo de las superficies primarias"],"correct":0,"expl":"Mach crítico es el número Mach de vuelo a partir del cual alguna zona del flujo local alcanza Mach 1.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, número Mach crítico.","src":"Material de entrevista LATAM · respuesta depurada","topic":"High-speed flight","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es Mach crítico?"},
{"q":"¿Qué describe el término Mach tuck?","options":["Una tendencia de cabeceo nariz abajo asociada a cambios aerodinámicos del flujo compresible a alta velocidad","Una tendencia de cabeceo nariz arriba asociada a la extensión de spoilers a números de Mach elevados","Una vibración estructural del fuselaje causada por resonancia del motor durante el crucero a alta altitud de vuelo","Un efecto de guiñada inducido por asimetría de empuje entre motores a números de Mach elevados en crucero"],"correct":0,"expl":"A medida que cambian la distribución de presiones y la posición del centro de presión a alta velocidad, puede aparecer una tendencia de pitch nose-down conocida como Mach tuck.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, Mach tuck.","src":"Material de entrevista LATAM · respuesta depurada","topic":"High-speed flight","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es Mach tuck?"},
{"q":"¿Qué describe el “coffin corner”?","options":["La reducción del margen entre el buffet de baja velocidad y el buffet de alta velocidad a gran altitud","La ampliación del margen entre VMO y la velocidad de pérdida a medida que se gana altitud de crucero","El punto exacto donde la velocidad de crucero óptima coincide con la velocidad de máximo alcance","La zona de la envolvente donde el consumo de combustible resulta mínimo para cualquier peso de la aeronave"],"correct":0,"expl":"A gran altitud puede estrecharse el margen entre el límite por alto ángulo de ataque y el límite por efectos compresibles.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, coffin corner.","src":"Material de entrevista LATAM · respuesta depurada","topic":"High-speed flight","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame qué significa coffin corner y por qué el margen de velocidad se reduce."},
{"q":"¿Qué información fundamental entrega un ILS?","options":["Guía lateral mediante localizer y guía vertical mediante glideslope","Guía vertical mediante localizer y guía lateral mediante marker beacon","Guía lateral mediante DME y guía vertical mediante VOR","Distancia mediante localizer y rumbo mediante glideslope"],"correct":0,"expl":"El localizer proporciona guía lateral y el glideslope guía vertical en una aproximación ILS.","cite":"Origen: PREGUNTAS TÉCNICAS / PREGUNTAS LATAM / Resumen LATAM, ILS.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué componentes forman la guía básica de un ILS?"},
{"q":"Durante una aproximación ILS, el glideslope queda inoperativo pero el localizer continúa utilizable y existe un procedimiento publicado localizer-only. ¿Qué criterio es correcto?","options":["Continuar solo si se puede volar el procedimiento localizer publicado con sus mínimos y restricciones correspondientes","Continuar aplicando los mínimos normales de CAT II, ya que el localizer por sí solo garantiza esa precisión vertical","Rechazar automáticamente cualquier continuación de la aproximación y ejecutar missed approach sin evaluar alternativas","Continuar usando únicamente el DME para simular mentalmente una senda de 3° hasta el umbral de pista"],"correct":0,"expl":"La pérdida del glideslope elimina la guía vertical de precisión del ILS. Solo puede continuarse mediante un procedimiento autorizado/publicado que use el localizer y sus mínimos propios.","cite":"Origen: PREGUNTAS TÉCNICAS / Resumen LATAM, “ILS con GS INOP”. Respuesta contextualizada para evitar una regla insegura.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Vas en un ILS y pierdes el glideslope. ¿Qué necesitas comprobar antes de decidir continuar como localizer-only?","scenario_q":"Estás establecido en un ILS y la señal de glideslope se vuelve inutilizable. El localizer permanece estable y la carta contiene un procedimiento LOC con mínimos publicados. ¿Qué opción operacional corresponde?"},
{"q":"¿Cuál es la diferencia práctica entre DA/DH y MDA?","options":["En DA/DH se toma la decisión al alcanzar esa referencia sin planear un tramo nivelado; una MDA no debe ser descendida antes de cumplir las condiciones para continuar","En MDA se toma la decisión al alcanzar esa referencia sin nivelar; una DA/DH permite volar nivelado indefinidamente mientras se buscan las referencias visuales necesarias","DA/DH y MDA representan exactamente el mismo concepto operacional, y la única diferencia real es que uno se usa en español y el otro en inglés","La MDA se calcula sumando siempre 200 ft a la DA/DH publicada de esa misma pista en absolutamente todos los procedimientos de aproximación"],"correct":0,"expl":"DA/DH corresponde a una decisión durante un descenso continuo; MDA es una altitud mínima que no se debe infringir hasta que se cumplan los requisitos para continuar.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, MDA y DA/DH. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame la diferencia operacional entre una DA/DH y una MDA."},
{"q":"¿Qué representa RVR?","options":["El alcance visual de pista estimado/medido para un piloto sobre el eje de pista respecto de marcas o luces","La visibilidad meteorológica general reportada en el METAR para toda el área circundante del aeródromo","La distancia mínima legal que debe existir entre dos aeronaves durante la carrera de despegue en pista","La altura sobre el terreno a la que deben resultar visibles las luces del sistema de aproximación en uso en ese momento"],"correct":0,"expl":"RVR expresa la distancia a la que un piloto en el eje de pista podría ver marcas o luces relevantes de la pista; se usa especialmente en operaciones de baja visibilidad.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM. Revisión: FAA RVR.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es RVR y por qué no es simplemente “visibilidad”?"},
{"q":"¿Qué caracteriza a RNP frente a una especificación RNAV sin requisito de monitorización equivalente?","options":["Incluye un requisito de monitorización y alerta de performance de navegación a bordo","Exige el uso exclusivo de sensores inerciales, sin posibilidad de actualización por GNSS","Elimina la necesidad de cualquier margen de protección lateral en el diseño del procedimiento","Se limita a rutas oceánicas y no puede aplicarse a procedimientos de aproximación"],"correct":0,"expl":"RNP incorpora monitorización y alerta de la performance de navegación, además del requisito de precisión aplicable.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, RNP. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué distingue conceptualmente RNP de una navegación RNAV genérica?"},
{"q":"¿Qué es un VDP en una aproximación no precisión cuando está publicado?","options":["Un punto desde el cual puede iniciarse un descenso normal desde MDA hacia la pista si se cumplen los requisitos visuales","Un punto en el que se debe iniciar obligatoriamente el missed approach si aún no existen referencias visuales adecuadas para continuar","Un punto que marca únicamente el límite lateral de protección de obstáculos del procedimiento de aproximación","Un punto de la carta que indica dónde debe extenderse el tren de aterrizaje antes de continuar la aproximación"],"correct":0,"expl":"El VDP ayuda a iniciar un descenso estabilizado desde la MDA cuando existe referencia visual adecuada; no autoriza por sí mismo a bajar sin cumplir los requisitos visuales.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, VDP.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es un VDP y qué condición necesitas para usarlo?"},
{"q":"¿Qué significa que un localizer esté offset respecto de una pista?","options":["Que el curso final del localizer no está alineado exactamente con el eje de pista","Que la señal del localizer se recibe con retraso respecto de la del glideslope","Que el localizer transmite en una frecuencia distinta a la publicada en la carta de aproximación","Que el localizer solo puede usarse para aproximaciones circling, nunca rectas"],"correct":0,"expl":"Un localizer offset proporciona una final course que no coincide exactamente con la prolongación del eje de pista.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, LOC offset.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es un localizer offset y qué implica para la transición final a la pista?"},
{"q":"¿Cuáles son las tres entradas de holding convencionales que se enseñan como referencia?","options":["Directa, paralela y teardrop/gota de agua","Directa, circular y de radial cruzado","Paralela, visual y de interceptación por DME","Teardrop, lateral y de espera libre"],"correct":0,"expl":"Las entradas convencionales son direct, parallel y teardrop. La selección depende del sector de llegada al fix y del procedimiento aplicable.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, ingresos a holding.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Navigation","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Cuáles son las tres entradas clásicas a un holding?"},
{"q":"¿Qué ajuste representa QNH?","options":["La presión reducida al nivel medio del mar que permite que el altímetro indique aproximadamente la elevación del aeródromo en tierra","La presión real medida directamente en el aeródromo sin ninguna corrección, usada para que el altímetro indique cero en tierra al aterrizar","La presión estándar internacional que se utiliza siempre por encima de la altitud de transición aplicable en esa área","La presión corregida por temperatura exterior que se usa exclusivamente durante el despegue con FLEX seleccionado"],"correct":0,"expl":"Con QNH, el altímetro en el aeródromo indica aproximadamente su elevación sobre el nivel medio del mar.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, QNH-QFE-QNE. Terminología corregida.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Altimetry","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame QNH."},
{"q":"¿Qué efecto tiene ajustar QFE en el aeródromo de referencia?","options":["El altímetro indica aproximadamente cero en ese punto de referencia","El altímetro indica la altitud de vuelo directamente sobre el nivel medio del mar","El altímetro deja de funcionar hasta que se selecciona nuevamente QNH","El altímetro indica automáticamente la altura de decisión del procedimiento"],"correct":0,"expl":"QFE corresponde a la presión del datum/aeródromo y hace que el altímetro indique aproximadamente cero en ese punto.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, QFE. Respuesta corregida.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Altimetry","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué indicará el altímetro en el aeródromo si ajustas QFE?"},
{"q":"¿Qué referencia se utiliza para volar niveles de vuelo por encima de la altitude de transición?","options":["La presión estándar 1013.25 hPa / 29.92 inHg","El QNH del aeropuerto de destino previsto","El QFE promediado entre el aeropuerto de origen y el de destino previsto","La presión real de cabina indicada en ECAM"],"correct":0,"expl":"Los niveles de vuelo se basan en el ajuste altimétrico estándar.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, QNE/standard pressure.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Altimetry","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué ajuste altimétrico usas para niveles de vuelo?"},
{"q":"¿Qué representa la categoría de aproximación de una aeronave?","options":["Una clasificación basada en una velocidad de referencia de aproximación que condiciona mínimos y diseño de procedimientos","Una clasificación basada en el número de tripulantes certificados requeridos para operar ese tipo específico de aeronave comercial","Una clasificación basada exclusivamente en la envergadura alar total de la aeronave certificada para volar","Una clasificación que determina únicamente el tipo de combustible autorizado para esa aproximación específica"],"correct":0,"expl":"Las categorías A–E se basan en la velocidad de aproximación de referencia y se usan en el diseño/protección de procedimientos y mínimos.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, categorías de aproximación. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿De qué depende la categoría de aproximación de una aeronave?"},
{"q":"¿Para qué sirven principalmente las approach lighting systems?","options":["Para ayudar a la transición desde referencias instrumentales a referencias visuales y proporcionar alineación/guía visual hacia la pista","Para reemplazar completamente la función del PAPI cuando la visibilidad cae por debajo de los mínimos publicados en la carta de aproximación","Para indicar únicamente a la torre de control qué pista específica está siendo utilizada en ese momento del día y hora","Para medir automáticamente el RVR de la pista y transmitirlo de forma directa al sistema ATIS del aeródromo en uso"],"correct":0,"expl":"Los sistemas de luces de aproximación facilitan la adquisición y continuación de referencias visuales durante la transición hacia la pista.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, approach lights.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué función operacional cumple un approach lighting system?"},
{"q":"¿Qué diferencia básica existe entre PAPI y VASI?","options":["Ambos entregan guía visual de senda vertical, pero utilizan disposiciones de luces diferentes","PAPI entrega guía visual vertical y VASI entrega exclusivamente guía lateral de alineación","Ambos son sistemas de radionavegación que transmiten en una frecuencia VHF compartida entre ellos","VASI se instala solo en pistas de tierra y PAPI únicamente en pistas pavimentadas certificadas"],"correct":0,"expl":"PAPI y VASI son ayudas visuales de senda de aproximación; el patrón de luces y su presentación difieren.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, PAPI-VASI. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué tienen en común PAPI y VASI y en qué se diferencian conceptualmente?"},
{"q":"¿Qué es un ETP?","options":["Un punto de la ruta donde el tiempo hasta dos referencias o alternos considerados es igual bajo las condiciones de cálculo","Un punto de la ruta exactamente equidistante en millas náuticas entre el aeropuerto de origen y el de destino final del vuelo","El punto donde se debe transmitir obligatoriamente la posición a ATC en cualquier ruta oceánica programada","El punto de la ruta con el menor consumo de combustible previsto según el plan de vuelo ya presentado"],"correct":0,"expl":"ETP significa Equal Time Point: igualdad de tiempo, no necesariamente de distancia, porque viento y performance pueden hacer distintas las distancias.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, ETP. Respuesta corregida.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Navigation","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es un ETP y por qué no tiene por qué ser el punto medio en distancia?"},
{"q":"¿Qué función cumple RAIM en receptores GNSS que utilizan esa capacidad?","options":["Monitorizar la integridad de la solución de navegación utilizando redundancia de señales disponibles","Corregir automáticamente la posición GPS utilizando datos del sistema inercial de respaldo disponible","Aumentar la precisión vertical del GPS para aproximaciones de precisión sin apoyo terrestre","Transmitir la posición de la aeronave a los centros de control mediante enlace satelital"],"correct":0,"expl":"RAIM es una función de monitorización de integridad del receptor; comprueba la coherencia de las mediciones disponibles.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, RAIM. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Navigation","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué hace RAIM?"},
{"q":"¿Qué es WAAS?","options":["Un sistema de aumentación satelital que mejora exactitud, integridad y disponibilidad del GPS en su área de servicio","Un sistema terrestre de radares secundarios que complementa la función del transpondedor en área terminal congestionada","Una red de estaciones DME/VOR que reemplaza completamente al GPS ante una eventual falla del satélite","Un modo de navegación exclusivo del FMGC que no depende de ninguna señal externa de referencia disponible"],"correct":0,"expl":"WAAS es un Satellite Based Augmentation System utilizado en Norteamérica para mejorar prestaciones del GPS.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, WAAS. Contextualizado como sistema regional.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Navigation","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es WAAS y qué mejora del GPS?"},
{"q":"¿Qué es RVSM?","options":["Un régimen que permite separación vertical reducida de 1 000 ft entre aeronaves aprobadas dentro del espacio aéreo RVSM","Un régimen que permite separación lateral reducida de 5 NM entre aeronaves dentro de cualquier espacio aéreo controlado","Un procedimiento que elimina por completo la necesidad de reportar posición en espacio aéreo no radarizado","Una autorización especial que permite volar sin transpondedor operativo en rutas oceánicas certificadas"],"correct":0,"expl":"RVSM permite reducir la separación vertical estándar entre niveles en el espacio designado, sujeto a aprobación y equipamiento/requisitos específicos.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, RVSM.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué significa RVSM y cuál es su objetivo?"},
{"q":"¿Qué significa “sterile cockpit” en términos operacionales?","options":["Durante fases críticas, se restringen conversaciones y actividades no relacionadas con la operación segura del vuelo","Durante todo el vuelo, incluido el crucero, está estrictamente prohibido cualquier tipo de conversación entre los pilotos","Solo aplica en tierra durante el rodaje, y deja de tener validez una vez iniciada la carrera de despegue","Aplica exclusivamente a las comunicaciones con la tripulación de cabina, nunca entre los dos pilotos"],"correct":0,"expl":"El concepto busca evitar distracciones durante fases críticas; no impide comunicaciones necesarias para la seguridad u operación.","cite":"Origen: PREGUNTAS TÉCNICAS / Resumen LATAM, cabina estéril. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué significa cabina estéril y qué busca prevenir?"},
{"q":"¿Qué elementos definen mejor una aproximación estabilizada?","options":["Trayectoria, velocidad, configuración, potencia y razón de descenso dentro de criterios establecidos por el operador a la altura de estabilización aplicable","Únicamente mantener el autopilot conectado hasta al menos 500 ft sobre el umbral de la pista de aterrizaje que fue seleccionada para esa operación específica","Solo depender de que la velocidad indicada coincida exactamente con VAPP durante absolutamente toda la aproximación final hasta el aterrizaje","Tener el tren extendido y los flaps en configuración de aterrizaje desde el mismo top of descent inicial de todo el descenso"],"correct":0,"expl":"Una aproximación estabilizada se evalúa como conjunto: trayectoria, energía, configuración y acciones mínimas requeridas. Los límites exactos pertenecen al SOP del operador.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, aproximación estabilizada. Respuesta corregida para no convertir criterios de un operador en universales.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Operations","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué entiendes por aproximación estabilizada?"},
{"q":"Tienes un pasajero gravemente enfermo en vuelo. ¿Cuál es el enfoque más adecuado?","options":["Coordinar con cabin crew, buscar asistencia médica disponible, obtener información clínica útil, evaluar aeropuertos/tiempos y tomar una decisión operacional coordinada con ATC y soporte disponible","Delegar toda la decisión médica y operacional en la tripulación de cabina, sin informar en ningún momento a ATC ni evaluar realmente el estado clínico del pasajero ni las opciones disponibles en ruta","Desviarse de inmediato al aeropuerto geográficamente más cercano, sin evaluar sus servicios médicos disponibles ni la meteorología real del lugar de destino","Esperar hasta el final del vuelo para informar del caso, salvo que el pasajero pierda completamente el conocimiento en algún momento durante la cabina"],"correct":0,"expl":"La decisión combina evaluación médica disponible y factores operacionales: gravedad, tiempo, aeropuertos adecuados, combustible, meteorología y asistencia en tierra.","cite":"Origen: PREGUNTAS TÉCNICAS / Resumen LATAM, “PAX enfermo”. Respuesta reescrita como escenario de CRM.","src":"Material de entrevista LATAM · respuesta depurada","topic":"CRM","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Te informan que un pasajero está gravemente enfermo. Háblame de tu proceso de decisión.","scenario_q":"En crucero, la jefa de cabina informa que un pasajero presenta un cuadro médico serio. Hay un médico a bordo y varios aeropuertos posibles en ruta. ¿Cómo estructuras la decisión?"},
{"q":"Antes del despegue existe una condición de windshear que te hace considerar que la operación no es segura, pero el comandante quiere continuar. ¿Qué actuación refleja mejor un buen CRM?","options":["Expresar claramente la preocupación con datos/procedimiento, verificar los límites aplicables y escalar la intervención si la seguridad sigue comprometida","Aceptar la decisión del comandante sin hacer ningún comentario adicional, ya que cuestionarla podría afectar negativamente el ambiente y la coordinación en cabina","Tomar el control físico de la aeronave de inmediato sin comunicar previamente el motivo real ni la preocupación al comandante","Informar por radio a la compañía y esperar su respuesta antes de decir absolutamente cualquier cosa en la cabina de mando"],"correct":0,"expl":"CRM exige comunicar una amenaza de forma clara y asertiva, usar procedimientos/datos y mantener el foco en la seguridad, respetando roles pero sin silenciar una preocupación crítica.","cite":"Origen: PREGUNTAS TÉCNICAS / Resumen LATAM, escenario windshear y desacuerdo con comandante.","src":"Material de entrevista LATAM · respuesta depurada","topic":"CRM","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"El comandante quiere despegar y tú consideras que el windshear hace la operación insegura. ¿Cómo manejas el desacuerdo?","scenario_q":"Están listos para despegar. Hay información de windshear relevante y tú consideras que no se cumplen condiciones seguras, pero el comandante quiere continuar. ¿Qué haces?"},
{"q":"¿Cuál es el objetivo principal de un briefing operacional bien hecho?","options":["Construir un modelo mental compartido, anticipar amenazas y acordar acciones/criterios antes de que aumente la carga de trabajo","Cumplir con un requisito puramente administrativo que debe completarse antes de cada despegue programado sin ninguna excepción posible","Demostrar ante el otro piloto el nivel de conocimiento técnico personal sobre el procedimiento a volar","Repasar en detalle cada ítem disponible del FCOM sin priorizar lo realmente relevante para ese vuelo"],"correct":0,"expl":"Un buen briefing prepara a la tripulación para lo probable y lo crítico, reduce ambigüedad y facilita una respuesta coordinada.","cite":"Origen: Resumen preguntas LATAM, importancia del briefing. Respuesta depurada con enfoque CRM.","src":"Material de entrevista LATAM · respuesta depurada","topic":"CRM","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Por qué es importante un briefing y qué hace que sea útil en vez de una recitación?"},
{"q":"Al declarar una emergencia, ¿qué información es especialmente útil comunicar a ATC cuando la situación lo permite?","options":["Naturaleza del problema, intenciones, posición/altitud cuando proceda y datos relevantes como combustible restante, personas a bordo y mercancías peligrosas si son necesarios","Únicamente el código de emergencia seleccionado en el transpondedor; cualquier otra comunicación adicional con ATC puede esperar hasta después de resuelta completamente la situación","Solo el nombre del comandante al mando y el número de vuelo, sin ningún otro detalle operacional relevante para la situación","Toda la lista completa de pasajeros y su documentación antes de mencionar siquiera la naturaleza real del problema en curso"],"correct":0,"expl":"La prioridad es volar el avión; cuando la carga de trabajo lo permite, ATC necesita entender la naturaleza de la emergencia y las intenciones, junto con datos útiles para coordinar asistencia.","cite":"Origen: Resumen preguntas LATAM, puntos especiales para informar en emergencia. Respuesta contextualizada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Emergencies","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué información intentarías darle a ATC durante una emergencia, una vez controlada la trayectoria?"},
{"q":"¿Qué criterio debe dominar una decisión de desvío?","options":["Seleccionar una opción adecuada considerando seguridad, tiempo, meteorología, performance, combustible, servicios y naturaleza del problema","Seleccionar siempre el aeropuerto de origen del vuelo, sin importar la distancia real, la meteorología ni el motivo específico del desvío en curso","Seleccionar el aeropuerto que ofrezca la tarifa de servicios en tierra más económica disponible en toda la zona","Seleccionar el aeropuerto que elijan directamente los pasajeros a través de la tripulación de cabina a bordo"],"correct":0,"expl":"“Nearest” y “suitable” no son conceptos idénticos. La urgencia de la situación determina cuánto peso tiene cada factor.","cite":"Origen: Material de entrevista LATAM, escenarios de emergencia y PAX enfermo. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Decision making","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Cuando dices que te desviarías, ¿cómo eliges a qué aeropuerto?"},
{"q":"¿Qué significa que una pista esté contaminada, en términos generales?","options":["Que una parte significativa de su superficie está cubierta por contaminantes como agua, nieve, slush o hielo en una magnitud que afecta performance/operación","Que la pista presenta cualquier mancha de humedad visible en su superficie, sin importar en absoluto su extensión ni su profundidad real observada en ese momento","Que la pista fue recientemente repavimentada y todavía no cuenta con sus marcas pintadas habituales de eje ni de borde","Que existen desechos de goma acumulados en la zona habitual de toma de contacto de esa pista en particular"],"correct":0,"expl":"La clasificación exacta depende del marco regulatorio y reporte de condición, pero el concepto operacional es que el contaminante afecta frenado/performance y exige considerarlo en los cálculos.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, pista contaminada. Redacción no numérica para evitar mezclar criterios regulatorios distintos.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Operations","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué entiendes por pista contaminada y por qué cambia tu cálculo de performance?"},
{"q":"¿Qué es hidroplaneo?","options":["La pérdida parcial o total de contacto efectivo neumático-pavimento debido a una película de agua, con degradación de frenado y control direccional","El aumento progresivo de la temperatura del neumático por fricción excesiva sobre una pista completamente seca y muy caliente durante el rodaje inicial","La pérdida de presión de un neumático causada por un aterrizaje realizado con exceso de velocidad vertical al contacto","Un desgaste irregular de la banda de rodadura producido por frenadas asimétricas repetidas a lo largo de varios vuelos"],"correct":0,"expl":"El hidroplaneo reduce la fricción disponible porque el neumático deja de mantener contacto efectivo con la superficie.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, hidroplaneo.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Operations","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es hidroplaneo y cuál es su consecuencia principal para el piloto?"},
{"q":"¿Qué función cumple el antiskid?","options":["Modula la presión de frenado para evitar el bloqueo de ruedas y aprovechar mejor la fricción disponible","Aplica siempre la máxima presión hidráulica disponible, independientemente de la condición real de la pista","Controla exclusivamente la dirección de la rueda de nariz durante el rodaje y la carrera de despegue","Reemplaza completamente la función de los spoilers de tierra durante la carrera de aterrizaje"],"correct":0,"expl":"El antiskid reduce presión cuando detecta una tendencia al skid y busca mantener una desaceleración eficaz sin bloqueo de rueda.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, antiskid.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Operations","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame qué hace el antiskid, no solo con qué sistema de automóvil se compara."},
{"q":"¿Cuál es el principio del autobrake?","options":["Comandar automáticamente frenado para alcanzar una desaceleración objetivo según el modo seleccionado y las condiciones de activación","Aplicar siempre una misma presión hidráulica fija, sin ajustarse en absoluto a la desaceleración real obtenida en cada aterrizaje realizado","Reemplazar por completo al antiskid durante cualquier aterrizaje realizado en pista contaminada, mojada o helada","Activar automáticamente la reversa máxima apenas las ruedas hacen contacto con la superficie de la pista de aterrizaje"],"correct":0,"expl":"En el aterrizaje (LO y MED), el autobrake busca una desaceleración objetivo y ajusta la presión según las condiciones: no aplica una presión fija. En un despegue abortado, MAX manda la presión máxima apenas se genera la orden de los ground spoilers.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, autobrake. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Operations","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Cuál es el principio de funcionamiento del autobrake?"},
{"q":"¿Qué aporta el thrust reverse durante la desaceleración?","options":["Una fuerza adicional de desaceleración al redirigir parte del flujo/empje del motor, reduciendo la demanda sobre los frenos según la situación","Una reducción automática de la velocidad de referencia de aterrizaje calculada previamente por el FMGC del avión antes de iniciar el descenso final","Sustentación negativa generada exclusivamente por los spoilers de tierra ya completamente extendidos sobre la pista de aterrizaje en uso","Control direccional adicional equivalente al del nosewheel steering durante todo el rodaje realizado en tierra"],"correct":0,"expl":"La reversa complementa otras fuentes de desaceleración. Su disponibilidad y técnica dependen del tipo de motor, SOP y condición de pista.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, thrust reverse. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Operations","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Para qué sirve la reversa y qué papel tiene respecto de los frenos?"},
{"q":"¿Qué significa que el A320 sea fly-by-wire?","options":["Que las órdenes del piloto se transmiten eléctricamente a computadores de control que generan órdenes a actuadores, dentro de las leyes de control aplicables","Que todas las superficies de control se mueven mediante motores eléctricos dedicados de forma independiente, sin ningún sistema hidráulico de respaldo disponible a bordo","Que el sidestick permanece conectado mecánicamente a los alerones como sistema de respaldo permanente durante todo el vuelo","Que el piloto automático es el único sistema capaz de comandar directamente las superficies de vuelo primarias en cualquier fase del vuelo"],"correct":0,"expl":"En el A320, los inputs del piloto son señales eléctricas procesadas por los flight control computers; los actuadores de las superficies principales son hidráulicos.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, fly-by-wire. Corregido para no afirmar que los impulsos eléctricos “dan señales a las bombas”.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué significa realmente fly-by-wire en un A320?"},
{"q":"¿Qué representa Green Dot en el PFD del A320 en configuración limpia?","options":["Una velocidad característica calculada que sirve como referencia de maniobra/eficiencia en clean configuration","La velocidad mínima de control demostrada con un motor inoperativo en configuración de despegue certificada para ese peso","La velocidad máxima permitida para la extensión inicial de flaps durante la fase de aproximación final","La velocidad de referencia de aterrizaje calculada automáticamente para la configuración flaps FULL seleccionada"],"correct":0,"expl":"Green Dot es una velocidad característica calculada para configuración clean y se utiliza como referencia operacional en varias fases/procedimientos.","cite":"Origen: Resumen preguntas LATAM, Green Dot. Referencia técnica: FCOM A320FAM 15 SEP 2025.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es Green Dot y en qué configuración la ves?"},
{"q":"¿Qué diferencia conceptual existe entre TOGA y FLEX en un despegue A320?","options":["TOGA solicita el máximo empuje de despegue disponible; FLEX utiliza una assumed temperature para obtener un empuje reducido cuando la performance lo permite","TOGA utiliza una assumed temperature para reducir el empuje disponible durante el despegue; FLEX en cambio siempre entrega el máximo empuje certificado disponible","TOGA y FLEX son la misma palanca física de empuje del motor, y solo cambia el nombre según la fase de vuelo en curso","FLEX se activa automáticamente de forma exclusiva cuando falla un motor durante la propia carrera de despegue en pista"],"correct":0,"expl":"FLEX es una técnica de reduced thrust basada en una temperatura asumida. TOGA mantiene disponible el rating máximo de despegue correspondiente.","cite":"Origen: Resumen preguntas LATAM, TOGA/FLEX. Referencia técnica: FCOM A320FAM 15 SEP 2025.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame la diferencia entre TOGA y FLEX en Airbus."},
{"q":"¿Qué diferencia conceptual existe entre FLEX y un takeoff derated?","options":["FLEX reduce el empuje mediante assumed temperature manteniendo disponible TOGA; un derate define un rating de empuje máximo reducido para esa condición/configuración","El derate reduce el empuje mediante una assumed temperature calculada dinámicamente para esa condición; FLEX en cambio define un rating máximo permanentemente reducido para ese motor","FLEX y derate son términos completamente intercambiables que describen exactamente el mismo procedimiento operacional de despegue","El derate solo puede aplicarse durante el aterrizaje del avión, nunca durante la carrera de despegue en pista disponible"],"correct":0,"expl":"La diferencia clave es que FLEX es assumed-temperature reduced thrust, mientras un derated rating establece un máximo de empuje más bajo dentro del rating seleccionado.","cite":"Origen: Resumen preguntas LATAM, DERATED vs FLEX. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Cuál es la diferencia conceptual entre FLEX y derated takeoff?"},
{"q":"¿Qué muestra principalmente el Flight Director?","options":["Órdenes de guía de pitch y roll que el piloto puede seguir para volar la trayectoria comandada por el sistema de flight guidance","La posición física exacta de cada superficie de control primaria en tiempo real durante todo el vuelo en curso actual","El estado de disponibilidad actual de los tres sistemas hidráulicos independientes de toda la aeronave completa en vuelo","La tendencia de viento cruzado calculada respecto del eje de pista seleccionado para el aterrizaje final previsto en la carta de aproximación"],"correct":0,"expl":"El FD presenta comandos de guía de vuelo sobre el PFD; no es un instrumento independiente que “vuele” el avión por sí mismo.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, Flight Director. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué información te entrega el Flight Director?"},
{"q":"¿Qué significa EFIS?","options":["Electronic Flight Instrument System: presentación electrónica de información primaria de vuelo y navegación","Engine Flight Indication System: presentación electrónica exclusiva de los parámetros de motor en vuelo","Emergency Flight Isolation System: reconfiguración eléctrica automática ante una emergencia a bordo declarada","Electronic Fuel Injection System: gestión electrónica de la inyección de combustible de cada motor"],"correct":0,"expl":"EFIS se refiere al sistema de presentación electrónica de instrumentos de vuelo; en el A320 se asocia principalmente a PFD/ND y sus controles.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, EFIS. Redacción corregida.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es EFIS en un A320?"},
{"q":"En un A320, ¿qué es más correcto afirmar sobre el uso de engine anti-ice?","options":["Debe seguirse el criterio publicado por Airbus para condiciones de engelamiento y la fase de vuelo; no basta con una regla genérica memorizada de otro tipo de avión","Debe activarse únicamente cuando se observa hielo visible ya acumulado directamente en el parabrisas del piloto durante el vuelo en curso","Debe permanecer siempre seleccionado en ON durante absolutamente todo el vuelo sin excepción alguna, sin importar en ningún caso cuál sea el valor real del TAT indicado","Debe activarse solamente en tierra durante el rodaje inicial y desconectarse obligatoriamente justo antes de iniciar la carrera de despegue programado"],"correct":0,"expl":"Los criterios exactos de anti-ice son específicos del avión/procedimiento. Las preguntas de entrevista deben evitar mezclar reglas de otros fabricantes o versiones.","cite":"Origen: Resumen preguntas LATAM, anti-ice. Referencia técnica: FCOM A320FAM 15 SEP 2025.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Cómo decides cuándo usar engine anti-ice en el A320?"},
{"q":"¿Qué debería hacer un piloto si durante una entrevista le preguntan un valor A320 que sabe que puede cambiar por versión de motor, MSN o equipamiento?","options":["Aclarar la configuración/effectivity antes de dar un valor absoluto y, si conoce la variante, responder para esa configuración","Responder con el valor que mejor recuerde, asumiendo que todas las variantes del A320 son básicamente idénticas entre sí en todo","Evitar por completo responder cualquier pregunta que incluya un número específico durante toda la entrevista técnica","Dar un rango amplio de valores posibles, sin aclarar en ningún momento que dependen realmente de la configuración"],"correct":0,"expl":"En A320 existen diferencias de effectivity reales. Una respuesta profesional distingue lo universal de lo dependiente de configuración.","cite":"Origen: criterio de auditoría aplicado al banco FCOM y a las preguntas de entrevista del proyecto.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Si te preguntan un dato que cambia por configuración del A320, ¿cómo responderías?"},
{"q":"¿Qué expresa V1?","options":["Una velocidad de decisión de despegue definida en performance, relacionada con las acciones de continuar o rechazar y con los requisitos accelerate-stop/accelerate-go","Una velocidad fija de 100 kt establecida por regulación internacional para todas las aeronaves de transporte comercial en cualquier condición de peso y balance previsto","La velocidad mínima a la que el avión puede volar de forma segura una vez que ya se encuentra completamente establecido en el aire","La velocidad máxima permitida para utilizar la reversa de empuje durante un aterrizaje completamente normal sin incidentes"],"correct":0,"expl":"V1 forma parte del cálculo de performance de despegue. La frase “después de V1 nunca se rechaza por ninguna circunstancia” es una simplificación inadecuada para una respuesta técnica.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, V1. Respuesta corregida.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Define V1 con precisión y dime por qué no te gusta llamarla simplemente “la velocidad después de la cual jamás abortas”."},
{"q":"¿Qué representa VR?","options":["La velocidad a la que se inicia la acción de rotación para alcanzar la actitud de despegue","La velocidad mínima de control direccional en tierra con un motor inoperativo durante el despegue","La velocidad objetivo de ascenso que se mantiene constante durante todo el segundo segmento","La velocidad exacta a la que el tren de aterrizaje se retrae automáticamente tras el despegue"],"correct":0,"expl":"VR es la rotation speed utilizada para iniciar la rotación del avión en el despegue.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, V1-VR-V2.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es VR?"},
{"q":"¿Qué representa V2?","options":["La takeoff safety speed utilizada como referencia de performance después del despegue, especialmente en el caso OEI","La velocidad exacta de contacto de la rueda de nariz con la pista durante toda la carrera de despegue","La velocidad máxima estructural permitida con los flaps en configuración de despegue totalmente extendida","La velocidad de decisión que determina si se continúa o se rechaza el despegue que está actualmente en curso en la pista"],"correct":0,"expl":"V2 es una velocidad de seguridad de despegue calculada; no debe definirse como “la velocidad que se mantiene solo hasta 35 ft”.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, V2. Respuesta corregida.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es V2?"},
{"q":"¿Qué diferencia existe entre perfil alar y cuerda geométrica?","options":["El perfil alar es la sección transversal del ala; la cuerda geométrica es la línea recta entre borde de ataque y borde de salida","El perfil alar es la línea recta entre los bordes de ataque y salida; la cuerda geométrica es la sección transversal completa del ala entera","Ambos términos describen exactamente la vista en planta del ala completa observada siempre desde arriba","El perfil alar corresponde a la envergadura total; la cuerda geométrica es la superficie alar expuesta al viento"],"correct":0,"expl":"La cuerda geométrica no debe confundirse con la línea media de curvatura. Es la línea recta que une leading edge y trailing edge.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, perfil alar/cuerda. Respuesta corregida.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Aerodynamics","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame perfil alar y cuerda geométrica."},
{"q":"¿Qué es un NOTAM?","options":["Un aviso distribuido por telecomunicaciones sobre establecimiento, condición o cambio de instalaciones, servicios, procedimientos o peligros cuyo conocimiento oportuno es esencial para las operaciones","Un pronóstico meteorológico específico de terminal, válido por un período determinado de entre 24 y 30 horas consecutivas para ese aeródromo en particular durante esa temporada específica del año en curso","Un reporte informal que un piloto transmite verbalmente a otro sobre condiciones de turbulencia encontradas durante su propio vuelo reciente en esa misma ruta","Una autorización emitida por ATC que modifica la ruta de un plan de vuelo ya presentado previamente por la tripulación a cargo"],"correct":0,"expl":"NOTAM comunica información operacional temporal o relevante que debe conocer el personal implicado en las operaciones de vuelo.","cite":"Origen: PREGUNTAS TÉCNICAS / PREGUNTAS LATAM 2022 / Resumen LATAM, NOTAM.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Navigation","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es un NOTAM y qué tipo de información esperas encontrar en él?"},
{"q":"¿Qué es el TCAS desde el punto de vista operacional?","options":["Un sistema embarcado de prevención de colisiones que vigila tráfico cooperante y puede generar Traffic Advisories y Resolution Advisories","Un radar meteorológico embarcado que detecta exclusivamente actividad convectiva severa y fenómenos de windshear cercano a la ruta de vuelo","Un sistema terrestre de ATC que transmite órdenes de evasión directamente al piloto automático de la aeronave en vuelo","Un receptor de navegación satelital utilizado únicamente para aproximaciones certificadas de tipo RNP AR publicadas"],"correct":0,"expl":"TCAS proporciona alertas de tráfico y, cuando corresponde, resolución vertical. No sustituye la separación ATC ni debe confundirse con radar meteorológico.","cite":"Origen: PREGUNTAS LATAM 2022, TCAS. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué hace TCAS y qué diferencia hay entre TA y RA?"},
{"q":"¿Qué diferencia conceptual existe entre speed brakes y ground spoilers?","options":["Las mismas superficies spoiler pueden cumplir funciones diferentes: aumentar drag en vuelo y descargar sustentación/ayudar a desacelerar en tierra según la lógica del sistema","Los speed brakes son superficies fijas instaladas de forma permanente en el borde de fuga del ala y los ground spoilers son en realidad los flaps de aterrizaje del avión completo","Ground spoilers actúan únicamente durante el vuelo en crucero y los speed brakes únicamente durante el rodaje realizado en tierra","Son dos sistemas hidráulicos completamente independientes entre sí, sin ninguna superficie física en común entre ambos"],"correct":0,"expl":"En muchos aviones, incluido el A320, spoilers individuales se utilizan con distintas funciones según la fase: speed brake, roll assistance y ground spoiler.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen LATAM, speed brakes y spoilers. Respuesta depurada.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Operations","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Explícame la diferencia funcional entre speed brakes y ground spoilers."},
{"q":"¿Qué es Mach buffet?","options":["Buffeting asociado a fenómenos de compresibilidad y ondas de choque a alta velocidad","Una vibración de baja frecuencia causada exclusivamente por la extensión del tren de aterrizaje","Una alerta sonora generada por el sistema de protección de stall a baja velocidad","Una oscilación del motor producida por desequilibrio de combustible entre alas"],"correct":0,"expl":"A alto Mach, ondas de choque y separación de flujo pueden producir buffet y reducir márgenes con respecto a los límites de alta velocidad.","cite":"Origen: PREGUNTAS LATAM 2022, Mach buffet.","src":"Material de entrevista LATAM · respuesta depurada","topic":"High-speed flight","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"¿Qué es Mach buffet?"},
{"q":"En una entrevista técnica, ¿qué es mejor hacer si no recuerdas con certeza un número exacto?","options":["Decir qué concepto sí conoces, aclarar que no estás seguro del valor y evitar inventarlo","Inventar un valor razonable para no perder fluidez ni dar una impresión de inseguridad ante el entrevistador","Cambiar rápidamente de tema hacia algo que sí domines por completo sin mencionar la duda existente","Responder con el valor equivalente de otro tipo de avión que hayas volado antes en tu carrera"],"correct":0,"expl":"En aviación, reconocer el límite de conocimiento es preferible a fabricar una cifra. Una buena respuesta puede explicar el concepto y señalar que verificarías el valor exacto.","cite":"Origen: criterio de preparación para entrevista y control de calidad del banco.","src":"Material de entrevista LATAM · respuesta depurada","topic":"CRM","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-10","quality_audit":"interview_bank_v1_2026-09-10","oral_q":"Si sabes el concepto pero no recuerdas el número exacto, ¿cómo lo manejarías frente a un entrevistador?"},
{"q":"¿Qué es ETOPS y qué umbral de tiempo activa históricamente su exigencia?","options":["Extended-range Twin-engine Operations, exigido cuando la ruta se aleja más de 60 minutos (velocidad crucero con un motor inoperativo) de un aeródromo adecuado","Extended-range Twin-engine Operations, exigido únicamente en rutas transoceánicas de más de 3000 millas náuticas totales de distancia recorrida","Extended Terminal Operations Standard, un requisito adicional aplicable solo a aproximaciones CAT III en cualquier tipo de aeronave certificada","Emergency Twin-engine Operational Procedure, un procedimiento activado automáticamente cuando falla un generador principal durante el vuelo en curso actualmente"],"correct":0,"expl":"ETOPS regula las operaciones de aeronaves bimotoras en rutas donde, en algún punto, la aeronave queda a más de 60 minutos (a velocidad de crucero con un motor inoperativo, en aire en calma) de un aeródromo de alternativa adecuado. Superado ese umbral, el operador y la aeronave necesitan una aprobación ETOPS específica (120, 180, etc.) que fija el tiempo máximo de desviación permitido.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen preguntas LATAM, ETOPS. Revisión: definición operacional estándar OACI.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v2_2026-09-13","oral_q":"Explícame qué es ETOPS y cuándo se vuelve obligatorio certificarlo."},
{"q":"¿Qué describe el criterio de pista balanceada (balanced field length)?","options":["Que la distancia requerida para abortar y detenerse dentro de la pista es igual a la requerida para continuar el despegue con un motor inoperativo hasta 35 ft, mediante la selección de V1","Que ASDA supera siempre a TODA en al menos un 15% adicional, dejando un margen extra considerable disponible para cualquier rechazo de despegue programado en esa pista específica del aeródromo","Que la pista cuenta con exactamente la misma pendiente longitudinal medida desde ambas cabeceras disponibles del aeródromo en cuestión específico","Que el peso máximo de despegue coincide siempre exactamente con el peso máximo estructural certificado de aterrizaje de esa aeronave"],"correct":0,"expl":"Balanced field length no describe una característica fija de la pista (ASDA=TODA), sino el resultado de elegir V1 de modo que la distancia de aceleración-parada requerida iguale a la de aceleración-continuación (OEI, hasta 35 ft), igual que en la otra pregunta de este banco sobre el mismo concepto.","cite":"V1 selected so that required accelerate-stop distance equals required accelerate-go distance (OEI, to 35 ft).","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v2_2026-09-13","oral_q":"¿Qué significa que una pista o un despegue esté “balanceado”?"},
{"q":"Dentro de los segmentos de despegue, ¿qué caracteriza al segundo segmento?","options":["Ascenso desde que el tren queda arriba hasta al menos 400 ft sobre la pista, a V2 y con takeoff thrust; es el segmento con el gradiente de ascenso mínimo más exigente","Ascenso desde 400 ft hasta 1500 ft AGL, con los flaps ya completamente retraídos y la potencia de máximo continuo aplicada durante ese tramo particular del vuelo en curso","Descenso controlado desde la altitud de crucero seleccionada hasta el punto de inicio de la aproximación final programada","Carrera en pista desde brake release hasta alcanzar la velocidad de rotación calculada para ese peso específico de la aeronave en ese momento"],"correct":0,"expl":"El second segment va desde que el tren queda totalmente arriba (el fin del first segment) hasta la acceleration altitude, como mínimo 400 ft sobre la pista, a V2, con takeoff thrust y flaps de despegue. En un bimotor exige 2,4%, el gradiente mínimo más alto de los cuatro segmentos, y es el que más suele limitar el peso.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen preguntas LATAM, “segmentos del despegue”.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v2_2026-09-13","oral_q":"Describime el segundo segmento del despegue y por qué se considera la fase crítica."},
{"q":"¿Qué exige el concepto de cabina estéril (sterile cockpit)?","options":["Que solo se realicen en cabina las actividades esenciales para la operación segura del vuelo durante fases críticas, como rodaje, despegue, ascenso y aproximación/aterrizaje por debajo de una altitud definida","Que ningún tripulante de la cabina de mando pueda comunicarse en absoluto con ATC salvo el comandante al mando, durante absolutamente todo el vuelo, incluido el crucero completo y también el descenso final hacia el aeropuerto","Que la cabina de pasajeros permanezca completamente en silencio durante el rodaje, el despegue y también durante todo el ascenso inicial hasta crucero","Que solo puedan usarse checklists impresas en papel físico a bordo, sin ninguna comunicación verbal permitida entre los dos pilotos en cabina"],"correct":0,"expl":"La regla de cabina estéril restringe las conversaciones y actividades no esenciales durante las fases críticas de vuelo (rodaje, despegue, ascenso y aproximación/aterrizaje, típicamente por debajo de 10.000 ft), para evitar distracciones cuando la carga de trabajo y el riesgo son mayores. No aplica de la misma forma en crucero.","cite":"Origen: PREGUNTAS TÉCNICAS, “cabina estéril”.","src":"Material de entrevista LATAM · respuesta depurada","topic":"CRM","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v2_2026-09-13","oral_q":"¿Qué es la cabina estéril y en qué fases de vuelo aplica?"},
{"q":"¿Qué distingue principalmente a las categorías de aproximación ILS (CAT I, II, III)?","options":["La altura de decisión (DH) y el RVR mínimo requeridos, que se reducen progresivamente de CAT I a CAT III","El fabricante específico del equipo de aviónica instalado a bordo de la aeronave que realiza la aproximación","La cantidad de antenas de localizer instaladas en el aeródromo que recibe esa categoría de aproximación","El tipo de combustible mínimo requerido en tanques antes de iniciar la aproximación de precisión"],"correct":0,"expl":"Las categorías de ILS se definen por la combinación de altura de decisión (DH) y alcance visual de pista (RVR) mínimos permitidos: CAT I exige DH y RVR mayores, CAT II los reduce, y CAT III (A/B/C) permite operar con DH muy bajas o inexistentes y RVR mínimos, requiriendo autoland y equipamiento certificado acorde.","cite":"Origen: PREGUNTAS TÉCNICAS / PREGUNTAS LATAM 2022, “categorías de ILS”. Revisión: definición estándar OACI Anexo 6.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v2_2026-09-13","oral_q":"Explícame qué diferencia a una aproximación CAT I de una CAT II o CAT III."},
{"q":"Según la separación estándar por estela turbulenta, ¿qué distancia mínima corresponde a un avión Medium detrás de un Heavy?","options":["5 NM","4 NM","6 NM","3 NM"],"correct":0,"expl":"La separación por estela turbulenta depende de las categorías de peso: Heavy detrás de Heavy son 4 NM, Medium detrás de Heavy 5 NM, y Light detrás de Heavy 6 NM (Light detrás de Medium, 5 NM). El A320 se clasifica como Medium, por lo que esta separación aplica directamente cuando sigue a un Heavy.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen preguntas LATAM, “separaciones entre aeronaves para evitar estela turbulenta”.","src":"Material de entrevista LATAM · respuesta depurada","topic":"IFR","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v2_2026-09-13","oral_q":"¿Qué separación por estela turbulenta te corresponde volando un A320 detrás de un Heavy?"},
{"q":"¿Qué diferencia a un stopway de un clearway?","options":["El stopway es un área preparada para soportar el peso del avión durante un despegue abortado; el clearway es un área libre de obstáculos que no necesita soportar ese peso","El clearway es un área preparada para soportar el peso completo del avión durante todo el despegue abortado, y el stopway solo debe permanecer libre de obstáculos en su superficie","Ambos términos son sinónimos regionales exactos del mismo concepto: stopway en la normativa OACI y clearway en la normativa FAA vigente actualmente","El stopway se declara únicamente para operaciones nocturnas y el clearway solamente para operaciones diurnas programadas en ese aeródromo específico"],"correct":0,"expl":"El stopway es una superficie preparada para resistir el peso de la aeronave en una parada abortada (extiende la ASDA), mientras que el clearway solo necesita estar libre de obstáculos —no requiere soportar el peso del avión— y extiende la TODA para la trayectoria inicial de ascenso tras un despegue continuado.","cite":"Origen: PREGUNTAS LATAM 2022 / Resumen preguntas LATAM, “TORA, TODA, ASDA, LDA, SWY y CLW”.","src":"Material de entrevista LATAM · respuesta depurada","topic":"Performance","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v2_2026-09-13","oral_q":"¿Cuál es la diferencia estructural entre un stopway y un clearway?"},
{"q":"¿Qué limitación debe respetar la tripulación al desconectar un IDG mediante su pushbutton?","options":["No mantener el pulsador presionado por más de unos 3 segundos, ya que un tiempo mayor puede dañar el solenoide de desconexión","Mantenerlo presionado hasta ver la luz FAULT completamente apagada, sin ningún límite de tiempo especificado por el fabricante","Verificar que el motor esté completamente detenido antes de accionar el pushbutton de desconexión correspondiente","Coordinar con mantenimiento antes de cada vuelo para autorizar formalmente el uso del pushbutton en tierra únicamente"],"correct":0,"expl":"Para desconectar un IDG el motor debe estar en marcha (o en windmilling) y se presiona brevemente el pushbutton guardado; no debe mantenerse presionado más de unos 3 segundos porque puede dañar el solenoide de desconexión. Una vez desconectado, el IDG solo puede volver a conectarse mediante una acción de mantenimiento en tierra, nunca en vuelo.","cite":"Origen: material de entrenamiento A320 (curso “Electrical System Abnormals”), IDG Disconnect.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿Qué cuidado hay que tener al presionar el pushbutton de desconexión de un IDG?"},
{"q":"Si un AC BUS falla por un corto o falla interna (no por pérdida de GEN o IDG), ¿qué diferencia clave existe en la lógica del bus tie?","options":["El bus tie no cierra para alimentar ese bus, a diferencia de una pérdida de generador donde sí cerraría automáticamente","El bus tie cierra de inmediato para alimentar ese bus desde el generador disponible del lado opuesto de toda la aeronave","El bus tie permanece cerrado de forma permanente desde el arranque hasta el apagado completo de ambos motores","El bus tie solo responde a comandos manuales de la tripulación, nunca actúa de forma automática en ningún caso"],"correct":0,"expl":"Cuando un generador o IDG se pierde sin que exista una falla en el propio bus, el bus tie cierra automáticamente para alimentar ese lado desde el generador restante. Pero si la falla es del propio AC BUS (por ejemplo, un corto), el sistema deliberadamente no cierra el bus tie hacia ese bus, para evitar alimentar una falla eléctrica real.","cite":"Origen: material de entrenamiento A320 (curso “Electrical System Abnormals”), AC BUS Fail.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿Por qué el bus tie no siempre cierra cuando se pierde un AC BUS?"},
{"q":"¿Qué puede provocar que el RAT (Ram Air Turbine) “stalle” y deje de generar presión/energía suficiente?","options":["Volar por debajo de aproximadamente 140 kt de velocidad, ya que el flujo de aire no alcanza para mantenerlo girando eficientemente","Volar por encima de aproximadamente 300 kt de velocidad indicada, generando una carga mecánica excesiva sobre la turbina en ese momento","Extender el tren de aterrizaje antes de que el RAT complete totalmente su despliegue durante la emergencia ya declarada","Operar con los flaps completamente extendidos durante más de cinco minutos consecutivos en fase de descenso final"],"correct":0,"expl":"El RAT depende del flujo de aire relativo para girar. Por debajo de aproximadamente 140 kt puede “stall” o no generar suficiente energía; en ese caso la red de emergencia se apoya automáticamente en baterías y el inversor estático, y se desprenden los buses AC/DC SHED ESS para preservar lo esencial.","cite":"Origen: material de entrenamiento A320 (curso “Emergency Power”), RAT Stalls.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿A qué velocidad puede stallar el RAT y qué pasa con la red eléctrica en ese caso?"},
{"q":"En configuración de emergencia eléctrica total, ¿qué ocurre con las pantallas EFIS/ECAM al reducir la velocidad por debajo de 50 kt?","options":["El AC ESS BUS se desprende automáticamente y todas las pantallas EFIS y ECAM quedan sin energía","El AC ESS BUS aumenta su capacidad automáticamente y todas las pantallas permanecen normales","Solo se apaga el reloj de cabina; el resto de las pantallas continúa funcionando sin cambios","El sistema transfiere automáticamente la carga al APU generator, restableciendo todas las pantallas"],"correct":0,"expl":"En este escenario (RAT/emergency generator ya insuficiente y solo baterías/inversor estático sosteniendo la red), al bajar de 50 kt el AC ESS BUS se desprende automáticamente, y con él se pierde la alimentación de todas las pantallas EFIS y ECAM. Es una consecuencia crítica que la tripulación debe anticipar en un escenario de pérdida eléctrica total a baja velocidad.","cite":"Origen: material de entrenamiento A320 (curso “Emergency Power”), Below 50 kts.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿Qué pasa con tus pantallas si en una emergencia eléctrica total tu velocidad cae por debajo de 50 kt?"},
{"q":"¿Qué diferencia existe entre presionar MAN ON en el panel EMER ELEC PWR y presionar RAT MAN ON en el panel hidráulico?","options":["Ambos despliegan el RAT, pero solo el del panel EMER ELEC PWR activa además la GCU del emergency generator","Ambos despliegan el RAT y activan la GCU por igual; la diferencia es solo la ubicación física del switch","Solo el del panel hidráulico despliega el RAT; el del panel eléctrico únicamente enciende una luz de aviso","Ninguno de los dos activa la GCU; esta se activa exclusivamente de forma automática sin intervención"],"correct":0,"expl":"Los dos switches pueden desplegar el RAT manualmente a cualquier velocidad (con riesgo de lesión si se hace en tierra). Pero solo el MAN ON del panel EMER ELEC PWR activa también la GCU del emergency generator para que empiece a generar electricidad; el RAT MAN ON del panel hidráulico únicamente da presión al sistema azul, sin activar esa GCU.","cite":"Origen: material de entrenamiento A320 (curso “Emergency Power”), Hyd. Panel RAT MAN ON.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿En qué se diferencian los dos switches de despliegue manual del RAT en el A320?"},
{"q":"Antes de seleccionar las baterías a AUTO, ¿qué voltaje mínimo se debe confirmar en cada batería?","options":["25.5 V","22 V","28.5 V","20 V"],"correct":0,"expl":"Antes de energizar las baterías se debe confirmar que el voltaje sin carga (unloaded) de cada una esté por encima de 25.5 V. Un valor por debajo de ese mínimo indica una batería insuficientemente cargada para sostener la red esencial en caso de necesitarla.","cite":"Origen: material de entrenamiento A320 (curso “Electrical System Controls and Operations”), Battery voltage minimum.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿Qué voltaje mínimo debe tener una batería antes de seleccionarla a AUTO?"},
{"q":"¿Qué condiciones encienden la luz FAULT de un IDG (además de la desconexión intencional)?","options":["Temperatura de salida de aceite por encima de aproximadamente 180°C, o presión de aceite baja (inhibida por debajo de 14% N2)","Temperatura de salida de aceite por debajo de aproximadamente 40°C, o presión de aceite excesivamente alta en ese circuito hidráulico","Únicamente una desconexión mecánica accidental detectada por el sensor de posición del generador asociado a ese motor","Solo una diferencia de frecuencia mayor a 2 Hz detectada entre ambos generadores principales de la aeronave completa"],"correct":0,"expl":"El IDG enciende su luz FAULT (con caution ECAM asociado) si la temperatura de salida de aceite supera aproximadamente 180°C, o si la presión de aceite es baja; esta protección está inhibida por debajo de 14% N2 para evitar falsas alarmas durante el arranque. La luz también se apaga cuando el IDG se desconecta intencionalmente.","cite":"Origen: material de entrenamiento A320 (curso “Electrical System Controls and Operations”), IDG Fault Light.","src":"Material de entrenamiento A320, corregido contra FCOM 15 SEP 25 · DSC-24","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿Qué condiciones encienden la luz FAULT de un IDG?"},
{"q":"¿Qué cargas controla específicamente el pushbutton COMMERCIAL del panel eléctrico?","options":["Luces de cabina y bodega, sistema de agua y toilets, protección antihielo del drain mast, galley, entretenimiento de pasajeros y carga semi-automática de bodegas","Iluminación de emergencia, suministro de oxígeno de la tripulación, sistema de comunicaciones VHF, el transpondedor secundario y las luces de balizamiento exterior","Instrumentos de vuelo esenciales, computadoras de datos aéreos y el sistema completo de piloto automático instalado a bordo","Bombas hidráulicas principales, generadores accionados por motor y el sistema de frenos normales de toda la aeronave completa"],"correct":0,"expl":"El pushbutton COMMERCIAL agrupa las cargas no esenciales para el vuelo pero sí para el servicio comercial: iluminación de cabina y bodegas, agua y toilets, protección antihielo del drain mast, galley, entretenimiento de pasajeros, y carga semi-automática de bodegas (si está instalada). En OFF, desconecta todas esas cargas a la vez.","cite":"Origen: material de entrenamiento A320 (curso “Electrical System Controls and Operations”), Commercial Pushbutton.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿Qué cargas agrupa el pushbutton COMMERCIAL?"},
{"q":"¿Para qué sirve el Maintenance Bus switch del sistema eléctrico?","options":["Permite energizar solo los circuitos necesarios para servicio en tierra, sin energizar todo el sistema eléctrico de la aeronave","Permite energizar todo el sistema eléctrico de la aeronave usando exclusivamente la batería principal disponible en ese momento","Transfiere el control completo del sistema eléctrico al personal de mantenimiento durante todo el vuelo programado en curso","Desconecta automáticamente ambas baterías cada vez que se conecta la unidad de poder externa en tierra"],"correct":0,"expl":"El Maintenance Bus switch permite que el personal de mantenimiento o servicio en tierra energice únicamente los circuitos necesarios para su trabajo, sin energizar todo el sistema eléctrico de la aeronave. Es un switch tipo magnético que queda enclavado en ON si hay EXT PWR disponible al seleccionarlo.","cite":"Origen: material de entrenamiento A320 (curso “Electrical System Controls and Operations”), Maintenance Bus Switch.","src":"Material de entrenamiento A320 · no verificado línea por línea contra FCOM","topic":"A320","audit":"interview_curated","bank":"interview_technical","editorial_audit":"2026-09-13","quality_audit":"interview_bank_v3_2026-09-13","oral_q":"¿Para qué sirve el Maintenance Bus switch?"}
]};
